// Parse RSS do RSSHub — pega title, link, description das últimas 20 msgs
const xml = String($input.item.json.data || $input.item.json);
const matches = [...xml.matchAll(/<item>[\s\S]*?<title>(.*?)<\/title>[\s\S]*?<link>(.*?)<\/link>[\s\S]*?<description>([\s\S]*?)<\/description>[\s\S]*?<pubDate>(.*?)<\/pubDate>[\s\S]*?<\/item>/g)];
const canal = $('Lista Canais TG').item.json.canal;

// Regex pra extrair links de dentro da description (afiliados alheios)
const extractLinks = (desc) => {
  const urls = [...desc.matchAll(/https?:\/\/[^\s"'<>]+/g)].map(m => m[0]);
  return urls.filter(u => !u.includes('t.me') && !u.includes('telegram')).slice(0, 3);
};

return matches.slice(0, 20).map(m => {
  const desc = m[3].replace(/<!\[CDATA\[|\]\]>/g, '').trim();
  const links = extractLinks(desc);
  return {
    json: {
      fonte: `telegram-${canal}`,
      titulo: m[1].replace(/<!\[CDATA\[|\]\]>/g, '').trim().slice(0, 200),
      descricao_original: desc.replace(/<[^>]+>/g, '').slice(0, 500),
      link_telegram: m[2].trim(),
      link_produto_extraido: links[0] || null,
      todos_links: links,
      publicado_em: m[4].trim(),
      coletado_em: new Date().toISOString()
    }
  };
}).filter(r => r.json.link_produto_extraido);

// Regera link com SUA tag de afiliado dependendo do domínio detectado
const item = $input.item.json;
const link = item.link_produto_extraido;
let linkComSuaTag = link;
let plataformaDetectada = 'outros';

if (link.includes('amazon.com.br') || link.includes('amzn.to')) {
  plataformaDetectada = 'amazon';
  // Se for amzn.to (encurtado), primeiro expande, senão adiciona tag
  if (link.includes('amazon.com.br')) {
    linkComSuaTag = link.includes('?') 
      ? `${link.split('?')[0]}?tag=${$env.AMAZON_PARTNER_TAG}`
      : `${link}?tag=${$env.AMAZON_PARTNER_TAG}`;
  }
} else if (link.includes('mercadolivre.com') || link.includes('mercadolibre.com')) {
  plataformaDetectada = 'mercadolivre';
  // ML precisa ir via API pra gerar seu link — placeholder
  linkComSuaTag = link + (link.includes('?') ? '&' : '?') + `matt_word=${$env.ML_AFFILIATE_ID}`;
} else if (link.includes('shopee.com.br') || link.includes('s.shopee')) {
  plataformaDetectada = 'shopee';
  linkComSuaTag = link + (link.includes('?') ? '&' : '?') + `sub_id=${$env.SHOPEE_AFFILIATE_ID}`;
} else if (link.includes('aliexpress.com') || link.includes('s.click.ali')) {
  plataformaDetectada = 'aliexpress';
  // Ali precisa passar pelo shortener oficial deles — chama API separada
}

return {
  json: {
    ...item,
    plataforma: plataformaDetectada,
    link_afiliado: linkComSuaTag
  }
};
